const CURRICULUM_SELECTION_DATE_KEY="biology-study:selection-date";
function localStudyDateKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;}
function curriculumSelectedToday(){return localStorage.getItem(CURRICULUM_SELECTION_DATE_KEY)===localStudyDateKey();}
