 const requestSubscription=async()=>{setSubscriptionMessage("");try{const snapshot=await submitSubscriptionRequest();setSubscriptionStatus(snapshot.status);setSubscriptionExpiresAt(snapshot.expiresAt);setSubscriptionRequestStatus(snapshot.requestStatus);setSubscriptionMessage("Your subscription request has been recorded. Enter the key when the administrator provides it.");return true;}catch(error){setSubscriptionMessage(error instanceof Error?error.message:"Could not submit your subscription request.");return false;}};
 const redeemSubscription=async(key:string)=>{setSubscriptionMessage("");const result=await redeemSubscriptionKey(key);setSubscriptionStatus(result.status);setSubscriptionExpiresAt(result.expiresAt);setSubscriptionRequestStatus(result.requestStatus);setSubscriptionMessage(result.message);return result.message;};
