 const [selectionConfigured,setSelectionConfigured]=useState(()=>curriculumSelectedToday());
 const [navNotice,setNavNotice]=useState("");const [selectedLessonId,setSelectedLessonId]=useState<string|null>(null);const premium=subscriptionStatus==="active";
