{showAuthSplash&&!authenticated&&<AuthSplash onComplete={()=>{setShowAuthSplash(false);if(sessionStorage.getItem("biology-study:authenticated")==="true")setAuthenticated(true);else setShowOnboarding(true);}}/>} {showOnboarding&&!showAuthSplash&&<Onboarding onCreate={finishOnboarding} onLogin={signIn} onAdminMode={()=>{sessionStorage.setItem("biology-study:auth-mode","admin");sessionStorage.removeItem("biology-study:authenticated");setAdminRequested(true);setAuthenticated(false);setShowAuthSplash(false);setShowOnboarding(false);}} onRecovery={()=>{setShowOnboarding(false);setShowRecovery(true);}}/>} {showVerification&&!showAuthSplash&&<VerificationScreen email={verificationEmail} onVerify={completeVerification} onResend={resendPendingEmail}/>} {showRecovery&&!showAuthSplash&&<RecoveryScreen onBack={()=>{setShowRecovery(false);setShowOnboarding(true);}} onComplete={(saved)=>{setAccount(saved);setShowRecovery(false);setAuthenticated(false);setShowAuthSplash(true);sessionStorage.setItem("biology-study:authenticated","true");}}/>} {locked&&!showOnboarding&&!showAuthSplash&&<AccountSwitcher accounts={getSavedAccounts()} currentAccount={account} onLogin={login} onSwitch={signIn} onAddAccount={()=>{setShowAuthSplash(false);setShowOnboarding(true);}}/>} {showEmailSetup&&!showAuthSplash&&!showOnboarding&&<EmailSetup account={account} onSaved={(saved)=>{setAccount(saved);setShowEmailSetup(false);}}/>} 
