function FeedbackPanel({account}:{account:LocalAccount|null}){
  const [message,setMessage]=useState("");
  const [name,setName]=useState(account?.studentName||"");
  const [sent,setSent]=useState(false);
  useEffect(()=>{setName(account?.studentName||"");},[account?.studentName]);
  const submit=(e:FormEvent)=>{
    e.preventDefault();
    const clean=message.trim();
    if(!clean)return;
    const source=`Source: Biology-Study Feedback | User: @${account?.username||"guest"} | Name: ${name.trim()||"Guest"}`;
    const text=`${source}\n\nFeedback:\n${clean}`;
    window.open(`https://wa.me/254114956729?text=${encodeURIComponent(text)}`,"_blank","noopener,noreferrer");
    setSent(true);
  };
  return (
    <div className="content">
      <section className="hero-grid">
        <div className="hero-card">
          <div>
            <span className="badge">💬 FEEDBACK</span>
            <h2>Tell us what should be better.</h2>
            <p>Send feedback, report an issue, suggest a feature or share your experience. Your message opens directly in WhatsApp for delivery.</p>
          </div>
        </div>
        <div className="streak-card">
          <span className="muted">Feedback channel</span>
          <strong>WhatsApp</strong>
          <span>+254 114 956729</span>
        </div>
      </section>
      <section className="panel feedback-panel">
        <div className="panel-heading">
          <div><span className="eyebrow">Direct feedback</span><h3>Write your message</h3></div>
          <span className="fact-tag">Source tagged automatically</span>
        </div>
        <form className="feedback-form" onSubmit={submit}>
          <label>Your name<input value={name} onChange={e=>setName(e.target.value)} maxLength={80} placeholder="Your name"/></label>
          <label>Feedback<textarea value={message} onChange={e=>{setMessage(e.target.value);setSent(false)}} maxLength={2000} required rows={8} placeholder="Tell us what you liked, what is broken, or what you would like us to add..."/></label>
          <div className="feedback-actions">
            <small>WhatsApp will open with your message and the Biology-Study source tag.</small>
            <button className="primary-button" disabled={!message.trim()}>Send via WhatsApp ↗</button>
          </div>
          {sent&&<div className="success-message">WhatsApp opened with your feedback prepared. Review it and press Send.</div>}
        </form>
      </section>
    </div>
  );
}
function Calendar({progress,onRefresh}:{progress:StudyProgress;onRefresh:()=>Promise<StudyProgress|null>}){
 const today=new Date();
 const [viewDate,setViewDate]=useState(()=>new Date(today.getFullYear(),today.getMonth(),1));
 const [selected,setSelected]=useState(()=>new Date(today.getFullYear(),today.getMonth(),today.getDate()));
 const [refreshing,setRefreshing]=useState(false);
 const cat=getCATStatus(progress);
 const pad=(n:number)=>String(n).padStart(2,"0");
 const key=(d:Date)=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
 const todayKey=key(today),selectedKey=key(selected);
 const lessonDays=new Map(progress.lessonHistory.map(item=>[item.completedAt.slice(0,10),item.lessonId]));
 const rats=new Set(progress.attempts.filter(a=>a.type==="RAT").map(a=>a.completedAt.slice(0,10)));
 const cats=new Set(progress.attempts.filter(a=>a.type==="CAT").map(a=>a.completedAt.slice(0,10)));
 const revisions=new Set(progress.revisionAttempts.map(a=>a.completedAt.slice(0,10)));
 const practices=new Set(progress.practiceSessions.map(a=>a.completedAt.slice(0,10)));
 const first=new Date(viewDate.getFullYear(),viewDate.getMonth(),1);
 const last=new Date(viewDate.getFullYear(),viewDate.getMonth()+1,0);
 const start=(first.getDay()+6)%7;
 const cells=Array.from({length:Math.ceil((start+last.getDate())/7)*7},(_,i)=>new Date(viewDate.getFullYear(),viewDate.getMonth(),i-start+1));
 const statusFor=(date:string)=>{const lesson=lessonDays.has(date),rat=rats.has(date),catDone=cats.has(date),revision=revisions.has(date),practice=practices.has(date);return {lesson,rat,cat:catDone,revision,practice,complete:lesson&&rat};};
 const selectedStatus=statusFor(selectedKey);
 const moveMonth=(amount:number)=>setViewDate(new Date(viewDate.getFullYear(),viewDate.getMonth()+amount,1));
 const goToday=()=>{setViewDate(new Date(today.getFullYear(),today.getMonth(),1));setSelected(new Date(today.getFullYear(),today.getMonth(),today.getDate()));};
 const sync=async()=>{setRefreshing(true);try{await onRefresh();}finally{setRefreshing(false);}};
 return <div className="content">
  <section className="hero-grid"><div className="hero-card"><div><span className="badge">🗓️ STUDY CALENDAR</span><h2>Your study history, synced.</h2><p>Completed tasks are synchronized with your saved account progress and marked <strong>DONE ✓</strong>.</p></div><div className="result-actions"><button className="secondary-button" onClick={goToday}>Today</button><button className="secondary-button" onClick={()=>void sync()} disabled={refreshing}>{refreshing?"Syncing...":"↻ Sync progress"}</button></div></div><div className="streak-card"><span className="muted">Assessment path</span><strong>{cat.eligible?"CAT OPEN":`${cat.ratDays}/3 RAT DAYS`}</strong><span>{cat.eligible?"CAT is available.":cat.remainingRATs>0?`${cat.remainingRATs} RAT day${cat.remainingRATs===1?"":"s"} remaining.`:"CAT opens the following day."}</span></div></section>
  <section className="panel calendar-panel"><div className="panel-heading"><div><span className="eyebrow">Monthly view</span><h3>{viewDate.toLocaleDateString(undefined,{month:"long",year:"numeric"})}</h3></div><div className="result-actions"><button className="secondary-button" onClick={()=>moveMonth(-1)} aria-label="Previous month">‹</button><button className="secondary-button" onClick={()=>moveMonth(1)} aria-label="Next month">›</button></div></div>
   <div className="calendar-grid calendar-weekdays">{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(d=><span key={d}>{d}</span>)}</div>
   <div className="calendar-grid calendar-days">{cells.map(date=>{const dkey=key(date),s=statusFor(dkey),sameMonth=date.getMonth()===viewDate.getMonth(),todayCell=dkey===todayKey,selectedCell=dkey===selectedKey;return <button key={dkey} type="button" className={`calendar-day${sameMonth?"":" muted-day"}${todayCell?" today":""}${selectedCell?" selected":""}`} onClick={()=>setSelected(date)}><div className="calendar-day-top"><strong>{date.getDate()}</strong>{s.complete&&<span className="calendar-done">✓ DONE</span>}</div><div className="calendar-dots">{s.lesson&&<i className="calendar-dot lesson" title="Lesson completed"/>}{s.rat&&<i className="calendar-dot rat" title="RAT completed"/>}{s.cat&&<i className="calendar-dot cat" title="CAT completed"/>}{s.revision&&<i className="calendar-dot revision" title="Revision completed"/>}{s.practice&&<i className="calendar-dot practice" title="Practice completed"/>}</div></button>})}</div>
   <div className="calendar-legend"><span><i className="calendar-dot lesson"/>Lesson</span><span><i className="calendar-dot rat"/>RAT</span><span><i className="calendar-dot cat"/>CAT</span><span><i className="calendar-dot revision"/>Revision</span><span><i className="calendar-dot practice"/>Practice</span><span className="calendar-done">✓ DONE</span></div>
  </section>
  <section className="dashboard-grid"><div className="panel"><div className="panel-heading"><div><span className="eyebrow">Selected day</span><h3>{selected.toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</h3></div>{selectedKey===todayKey&&<span className="badge success">TODAY</span>}</div>
   <div className="calendar-task-list"><CalendarTask title="Daily lesson" done={selectedStatus.lesson} detail={selectedStatus.lesson?(lessonDays.get(selectedKey)||"Lesson completed"):"Not completed"}/><CalendarTask title="RAT" done={selectedStatus.rat} detail={selectedStatus.rat?"RAT completed":"Not completed"}/><CalendarTask title="CAT" done={selectedStatus.cat} detail={selectedStatus.cat?"CAT completed":"No CAT completed"}/><CalendarTask title="Revision" done={selectedStatus.revision} detail={selectedStatus.revision?"Revision completed":"No revision recorded"}/><CalendarTask title="Practice" done={selectedStatus.practice} detail={selectedStatus.practice?"Practice completed":"No practice recorded"}/></div>
  </div><div className="panel"><div className="panel-heading"><div><span className="eyebrow">Daily completion</span><h3>{selectedStatus.complete?"DAY COMPLETE ✓":"Tasks remaining"}</h3></div></div><div className="calendar-completion"><strong>{[selectedStatus.lesson,selectedStatus.rat].filter(Boolean).length}/2</strong><span>core daily tasks completed</span><div className="progress"><i style={{width:`${[selectedStatus.lesson,selectedStatus.rat].filter(Boolean).length*50}%`}}/></div></div><p className="settings-note">The core chain is <strong>Lesson → RAT</strong>. Revision and practice are also synchronized.</p><div className="calendar-plan"><div><strong>{cat.ratDays}/3</strong><span>consecutive RAT days</span></div><div><strong>{cat.remainingRATs}</strong><span>RAT days remaining</span></div><div><strong>{cat.eligible?"OPEN":"LOCKED"}</strong><span>CAT status</span></div></div></div></section>
 </div>;
}
function CalendarTask({title,done,detail}:{title:string;done:boolean;detail:string}){return <div className={`calendar-task ${done?"done":"pending"}`}><span className="calendar-task-icon">{done?"✓":"○"}</span><div><strong>{title}</strong><small>{detail}</small></div><b>{done?"DONE":"PENDING"}</b></div>}
export default App;
